cd /tmp; sed -n 1405,1455p hmh.cc; B=https://chromium.googlesource.com/chromium/src/+/HEAD; curl -sL "$B/ui/views/win/?format=JSON" | jq -r '.entries[].name' | grep -i -E 'manip|direct'; curl -s "https://chromium.googlesource.com/chromium/src/+search/?q=DirectManipulationHandler" -o /dev/null -w '%{http_code}\n'; curl -sL "$B/ui/base/win/hidden_window.h?format=TEXT" -o /dev/null; for p in ui/views/win/direct_manipulation_handler.cc ui/base/win/direct_manipulation_helper.cc content/browser/renderer_host/direct_manipulation_helper_win.cc ui/views/win/direct_manipulation_handler_win.cc; do echo $p $(curl -sL "$B/$p?format=TEXT" | base64 -d 2>/dev/null | wc -l); done
